local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

--- from:
---@class CompetePlayerRankingsDialog
---@field Env                           	CompetePlayerRankingsDialog
---@field controller                    	Engine.UI.UILuaDialog
---@field FontStyleButton               	UnityEngine.RectTransform
---@field LayoutListAndMyselef          	UnityEngine.RectTransform
---@field MyRanking                     	UnityEngine.RectTransform
---@field LoopView                      	SuperScrollView.LoopListView2
local CompetePlayerRankingsDialog = Class("CompetePlayerRankingsDialog")
local CompetePlayerRankingNode = "Game.Activity.Compete.CompetePlayerRankingNode"

function CompetePlayerRankingsDialog:__init() 
    self._rankData = nil                --排行榜数据
    self._rankMeData = nil              --自己的数据
    ---@type CompeteComponent
    self.comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CompeteComponent)
end

function CompetePlayerRankingsDialog:__delete()
    self._rankData = nil
    self._rankMeData = nil
    self.comp = nil
end

function CompetePlayerRankingsDialog:Awake()

end

function CompetePlayerRankingsDialog:RequestData()
    GameUtils.Request(Interfaces.ActivityUserPkRank, { activityUuid = self.comp:GetActivityUuid() }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            data.activityUuid = self.comp:GetActivityUuid()
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            ---@type PlayerDojo
            local playerDojo =  playerComponent:GetPlayerDojo()
            self._rankData = data.randInfo
            for i = 1, #self._rankData do
                self._rankData[i].rankNum = i
            end
            self._rankMeData = data.playerRank
            local playerInfo = {
                name = playerDojo.playerName ,
                avatar = playerDojo.playerAvatar ,
                avatarFrame = playerDojo.avatarFrame ,
                level = playerDojo.level ,
                score = data.playerRank.point ,
                rankNum = data.playerRank.ranking
            }
            table.merge(self._rankMeData , playerInfo)
            self:FillSelf()
        end
    end)
end

function CompetePlayerRankingsDialog:FillSelf()
    self.LoopView:InitListView(#self._rankData, Bind(self, self.OnGetCellByIndex))
    self:FillMeRank()
end


function CompetePlayerRankingsDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._rankData[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, CompetePlayerRankingNode)
    if scr then
        scr:Refresh(data)
    end
    return cell
end

function CompetePlayerRankingsDialog:LookRankRewardsClick()
    ---@type CompeteComponent
    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CompeteComponent)
    local dialogConf = comp:GetPrefabDialogConf()
    UIModule.OpenDialog({id = dialogConf.RANKING_LOOK_REWARD} )
end

--绘制自己的排行信息
function CompetePlayerRankingsDialog:FillMeRank()
    if not self._rankMeData then
        return
    end
    KTool.SetActive(self.MyRanking, true)
    local scr = CfUtils.GetLuaScr(self.MyRanking, CompetePlayerRankingNode)
    if scr then
        scr:Refresh(self._rankMeData, true)
        scr:FillPercentageRank(self._rankMeData)
    end
end

function CompetePlayerRankingsDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RequestData()
        SetButtonAction(self.FontStyleButton , Bind(self, self.LookRankRewardsClick))
    end))
    return coWait
end

function CompetePlayerRankingsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CompetePlayerRankingsDialog
